const express = require('express');
const { exec } = require('child_process');
const path = require('path');
const fs = require('fs');

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Utility: sanitize filename (basic check)
function sanitizeFilename(name) {
  // Remove path traversal attempts
  return name.replace(/\.\.\//g, '').replace(/\.\.\\/, '');
}

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

// PDF generation endpoint - converts markdown files to PDF
app.post('/api/convert', (req, res) => {
  const { filename, outputFormat } = req.body;

  if (!filename) {
    return res.status(400).json({ error: 'filename is required' });
  }

  const sanitized = sanitizeFilename(filename);
  const inputPath = path.join('/app/uploads', sanitized);

  // Verify file exists before conversion
  if (!fs.existsSync(inputPath)) {
    return res.status(404).json({ error: 'File not found' });
  }

  const format = outputFormat || 'pdf';
  const outputPath = path.join('/app/output', `${path.basename(sanitized, path.extname(sanitized))}.${format}`);

  // Use pandoc for conversion
  const cmd = `pandoc ${inputPath} -o ${outputPath} --pdf-engine=xelatex`;

  exec(cmd, { timeout: 30000 }, (error, stdout, stderr) => {
    if (error) {
      return res.status(500).json({ error: 'Conversion failed', details: stderr });
    }
    res.json({ success: true, output: outputPath });
  });
});

// Diagnostic endpoint for ops team
app.get('/api/diagnostics', (req, res) => {
  const tool = req.query.tool || 'df';
  const target = req.query.target || '/';

  // Whitelist of allowed diagnostic tools
  const allowedTools = ['df', 'du', 'free', 'uptime', 'ls'];

  if (!allowedTools.includes(tool)) {
    return res.status(403).json({ error: 'Tool not permitted' });
  }

  // Build command with target parameter
  const command = `${tool} ${target}`;

  exec(command, { timeout: 5000 }, (error, stdout, stderr) => {
    if (error) {
      return res.status(500).json({ error: stderr || error.message });
    }
    res.json({ tool, target, output: stdout });
  });
});

// Log viewer for application logs
app.get('/api/logs', (req, res) => {
  const lines = parseInt(req.query.lines) || 100;
  const logFile = req.query.file || 'app.log';

  const safeName = sanitizeFilename(logFile);
  const logPath = path.join('/app/logs', safeName);

  const cmd = `tail -n ${lines} ${logPath}`;

  exec(cmd, (error, stdout, stderr) => {
    if (error) {
      return res.status(500).json({ error: 'Could not read log file' });
    }
    res.json({ file: safeName, lines: stdout.split('\n') });
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Document conversion service running on port ${PORT}`);
});
